extra_head_css:
.tab-btn { padding: 8px 20px; border-radius: var(--radius-sm); font-weight: 500; font-size: .85rem; background: var(--bg-tertiary); border: 1px solid var(--border-color); }
    .tab-btn.active { background: var(--accent); color: white; border-color: var(--accent); }
    .base64-output { width: 100%; min-height: 120px; background: var(--bg-secondary); border: 1px solid var(--border-color); border-radius: var(--radius-md); padding: 12px; font-family: monospace; font-size: .75rem; color: var(--text-secondary); resize: vertical; }
